do $$begin if not has_function_privilege('service_role','confirm_practice_block_v14(uuid,uuid,date)','EXECUTE') or (select prosecdef from pg_proc where oid='confirm_practice_block_v14(uuid,uuid,date)'::regprocedure) then raise exception 'VERIFICACION_091: seguridad incorrecta de confirm_practice_block_v14(uuid,uuid,date)';end if;end $$;
do $columns$ declare r record;begin
 for r in select * from (values
 ('notifications','user_id','INSERT'),('notifications','tipo','INSERT'),('notifications','titulo','INSERT'),('notifications','mensaje','INSERT'),('notifications','practice_slot_id','INSERT'),('notifications','scheduled_at','INSERT'),('notifications','email_status','INSERT'),('notifications','block_offer_group','INSERT'),
 ('notifications','titulo','UPDATE'),('notifications','mensaje','UPDATE'),('notifications','practice_slot_id','UPDATE'),('notifications','scheduled_at','UPDATE'),('notifications','created_at','UPDATE'),('notifications','read_at','UPDATE'),
 ('practice_slots','cohort_id','INSERT'),('practice_slots','instructor_id','INSERT'),('practice_slots','student_id','INSERT'),('practice_slots','scheduled_at','INSERT'),('practice_slots','duration_minutes','INSERT'),('practice_slots','status','INSERT'),
 ('practice_slots','cohort_id','UPDATE'),('practice_slots','student_id','UPDATE'),('practice_slots','status','UPDATE'),('practice_slots','confirmed_at','UPDATE'),('practice_slots','confirmation_notified_at','UPDATE'),('practice_slots','release_notified_at','UPDATE'),
 ('enrollments','practice_plan','UPDATE'),('enrollments','reprogramaciones_usadas','UPDATE'),
 ('practice_slot_cancellations','block_slot_ids','INSERT'),('practice_slot_cancellations','block_hours','INSERT'),('practice_slot_cancellations','block_local_date','INSERT'),('practice_slot_cancellations','repuesto_por_slot_id','UPDATE'),('practice_slot_cancellations','repuesto_en','UPDATE')
 ) v(tab,col,priv) loop
 if not has_column_privilege('service_role','public.'||r.tab,r.col,r.priv) then raise exception 'VERIFICACION_091: falta % en %.%',r.priv,r.tab,r.col;end if;
 end loop;
end $columns$;
select e.id,(s.scheduled_at at time zone 'America/Guayaquil')::date fecha,count(*) horas,count(distinct s.instructor_id) instructores
 from public.enrollments e join public.practice_slots s on s.student_id=e.student_id and s.cohort_id=e.cohort_id
 where e.status='activo' and s.status in('asignado','confirmado') and e.practice_plan->>'horasPorDia' in('1','2')
 group by e.id,(s.scheduled_at at time zone 'America/Guayaquil')::date
 having count(*) not in(1,2) or count(distinct s.instructor_id)<>1 or max(s.scheduled_at)-min(s.scheduled_at)<>make_interval(hours=>count(*)::integer-1);
do $$begin if not has_function_privilege('service_role','instructor_practice_blocks_v14(uuid,date,date)','EXECUTE') or (select prosecdef from pg_proc where oid='instructor_practice_blocks_v14(uuid,date,date)'::regprocedure) then raise exception 'VERIFICACION_091: seguridad incorrecta de instructor_practice_blocks_v14(uuid,date,date)';end if;end $$;
do $security$ declare f record;begin for f in select p.oid,p.oid::regprocedure sig,p.prosecdef,p.proconfig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','private') and p.proname like '%v14' loop
 if f.prosecdef or not coalesce(f.proconfig @> array['search_path=""'],false) or has_function_privilege('anon',f.oid,'EXECUTE') or has_function_privilege('authenticated',f.oid,'EXECUTE') or not has_function_privilege('service_role',f.oid,'EXECUTE') then raise exception 'VERIFICACION_091: seguridad incorrecta: %',f.sig;end if;
 end loop;end $security$;
