select id,student_id,practice_plan->>'horasPorDia' horas_por_dia,'Duración histórica fuera de bloques de 1 o 2 horas; revisar sin cambiar datos' motivo from public.enrollments where status='activo' and practice_plan is not null and coalesce(practice_plan->>'horasPorDia','') not in('1','2');
